CREATE VIEW v_school_profile AS SELECT schools.CDSCode, schools.School, schools.District, schools.County, schools.City, schools.Zip, schools.Latitude, schools.Longitude, schools.Charter, schools.FundingType, frpm."Academic Year" AS academic_year, frpm."Charter School (Y/N)" AS charter_school_yn, frpm."Enrollment (K-12)" AS enrollment_k12, frpm."Free Meal Count (K-12)" AS free_meal_count, frpm."Percent (%) Eligible Free (K-12)" AS pct_eligible_free, frpm."FRPM Count (K-12)" AS frpm_count, frpm."Percent (%) Eligible FRPM (K-12)" AS pct_eligible_frpm, satscores.rtype, satscores.enroll12, satscores.NumTstTakr, satscores.AvgScrRead, satscores.AvgScrMath, satscores.AvgScrWrite, satscores.NumGE1500, schools.StatusType, schools.Street, schools.State, schools.MailStreet, schools.Phone, schools.OpenDate, schools.ClosedDate, schools.CharterNum, schools.DOC, schools.SOC, schools.EdOpsCode, schools.GSoffered, schools.GSserved, schools.Virtual, schools.Magnet, schools.AdmFName1, schools.AdmLName1, schools.AdmEmail1, schools.AdmFName2, schools.AdmLName2, schools.AdmEmail2, schools.AdmFName3, schools.AdmLName3, frpm.CDSCode AS frpm_CDSCode, frpm."District Code", frpm."District Name", frpm."School Name", frpm."School Type", frpm."NSLP Provision Status", frpm."Charter Funding Type", frpm."Enrollment (Ages 5-17)", frpm."Free Meal Count (Ages 5-17)", frpm."FRPM Count (Ages 5-17)", satscores.cds, satscores.sname FROM schools LEFT JOIN frpm ON schools.CDSCode = frpm.CDSCode LEFT JOIN satscores ON schools.CDSCode = satscores.cds;
